-- Short links the committee runs (uclhiking.org/e/…, /media/…), served by the
-- app instead of next.config so they can be repointed without a deploy.
-- Matched ignoring case, as Next's own redirects were.
create table if not exists public.club_links (
  id bigint generated always as identity primary key,
  path text not null check (path ~ '^/(e|media)/[A-Za-z0-9._~/-]{1,200}$'),
  path_key text generated always as (lower(path)) stored unique,
  destination text not null check (length(destination) between 1 and 2000),
  note text not null default '' check (length(note) <= 200),
  updated_by uuid references public.members(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.club_links enable row level security;
revoke all on public.club_links from anon, authenticated;

create trigger club_links_set_updated_at before update on public.club_links
  for each row execute function public.set_updated_at();

-- The links imported from Wix, until now fixed in src/lib/redirects.ts.
on conflict do nothing;
